glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec2 a_uv0;
in vec4 a_color;
#if USE_TINT
  in vec4 a_color0;
#endif
out vec4 v_color;
out vec2 v_uv0;
#if USE_TINT
  out vec4 v_dark;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
    pos = cc_matViewProj * cc_matWorld * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  #if USE_TINT
    v_dark = a_color0;
  #endif
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in vec2 v_uv0;
#if USE_TINT
  in vec4 v_dark;
#endif
uniform sampler2D texture;
uniform TintParams {
  vec4 tintParams;
};
uniform BuiltinSpriteMode {
  float useBuiltinSprite;
};
vec3 saturateColor(vec3 color, float saturation) {
  float luma = dot(color, vec3(0.299, 0.587, 0.114));
  return mix(vec3(luma), color, saturation);
}
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  if (useBuiltinSprite > 0.0) {
    gl_FragColor = o * v_color;
  } else {
    float gray  = dot(o.rgb, vec3(0.299, 0.587, 0.114));
    float alpha = o.a * v_color.a;
    vec3 rawColor = v_color.rgb;
    #if USE_TINT
      rawColor = ((o.a - 1.0) * v_dark.a + 1.0 - o.rgb) * v_dark.rgb + o.rgb * v_color.rgb;
    #endif
    vec3 baseColor = saturateColor(rawColor, 1.12);
    baseColor = clamp(baseColor * 1.06, 0.0, 1.0);
    vec3 shadowBase = baseColor * tintParams.x;
    vec3 shadowColor = mix(shadowBase, baseColor, 0.22);
    vec3 highlightColor = baseColor + (vec3(1.0, 0.98, 0.92) - baseColor) * min(tintParams.y * 1.15, 1.0);
    float darkFactor  = clamp(gray * 2.0, 0.0, 1.0);
    float lightFactor = clamp((gray - 0.38) / 0.62, 0.0, 1.0);
    float volumeFactor = smoothstep(0.18, 0.82, gray);
    darkFactor  = pow(darkFactor,  tintParams.z);
    lightFactor = pow(lightFactor, tintParams.w);
    vec3 result = mix(shadowColor, baseColor, darkFactor);
    result += baseColor * volumeFactor * 0.16;
    result      = mix(result, highlightColor, lightFactor);
    result      = saturateColor(result, 1.06);
    result      = clamp((result - 0.5) * 1.08 + 0.5, 0.0, 1.0);
    gl_FragColor = vec4(result, alpha);
  }
  ALPHA_TEST(gl_FragColor);
}

